import { Cart } from "./cart.ts";
import { StockBook } from "./stock.ts";
import { ShipmentQueue } from "./shipping.ts";

type OrderState = "created" | "paid" | "shipped" | "cancelled";
interface Order { id: string; state: OrderState; amount: number; items: Array<{ sku: string; count: number }> }

export class Orders {
  private records = new Map<string, Order>();
  private stock: StockBook;
  private shipping: ShipmentQueue;
  constructor(stock: StockBook, shipping: ShipmentQueue) {
    this.stock = stock;
    this.shipping = shipping;
  }

  create(id: string, cart: Cart) {
    if (this.records.has(id)) throw new Error("duplicate order");
    const items = cart.items().map((item) => ({ sku: item.sku, count: item.quantity }));
    if (!items.length || !this.stock.reserve(id, items)) return false;
    this.records.set(id, { id, state: "created", amount: cart.total(), items });
    return true;
  }

  pay(id: string, amount: number, distance: number, timestamp: number) {
    const order = this.records.get(id);
    if (!order || order.state !== "created" || amount !== order.amount) return false;
    order.state = "paid";
    this.shipping.enqueue(id, distance, timestamp);
    return true;
  }

  dispatch(limit: number) {
    const ids = this.shipping.take(limit);
    for (const id of ids) {
      const order = this.records.get(id)!;
      order.state = "shipped";
      this.stock.commit(id);
    }
    return ids;
  }

  cancel(id: string) {
    const order = this.records.get(id);
    if (!order || order.state !== "created") return false;
    this.stock.release(id);
    order.state = "cancelled";
    return true;
  }

  find(id: string) {
    const order = this.records.get(id);
    return order ? { ...order, items: order.items.map((item) => ({ ...item })) } : undefined;
  }
}

baseline.src/pricing.ts:
export const minorUnit = 1;
const supportedCurrencies = new Set(["CNY", "USD", "EUR"]);
const taxRates = new Map([["CNY", 0.13], ["USD", 0.07], ["EUR", 0.19]]);

/** 折扣使用比例，价格使用当前货币的主单位。 */
export function applyDiscount(price: number, rate: number = 0.1, currency?: string): number {
  if (price < 0) throw new RangeError("price");
  const normalized = supportedCurrencies.has(currency ?? "CNY") ? currency! : "CNY";
  const maximum = normalized === "EUR" ? 0.75 : 0.8;
  const bounded = Math.min(maximum, Math.max(0, rate));
  const discounted = Math.round(price * (1 - bounded) * 100) / 100;
  return discounted * minorUnit;
}

export const discountedPrice = applyDiscount;

export function quote(price: number, rate: number = 0.1, currency?: string) {
  const amount = discountedPrice(price, rate, currency);
  const tax = amount * (taxRates.get(currency ?? "CNY") ?? 0.13);
  return { amount, tax };
}

export function taxableAmount(price: number, rate: number = 0.1, currency?: string): number {
  if (price < 0) throw new RangeError("tax base");
  const base = Math.max(0, price - 10);
  const reduction = currency === "EUR" ? Math.min(rate, 0.15) : rate;
  const result = Math.round(base * (1 - reduction) * 100) / 100;
  return result * minorUnit;
}

export function serviceFee(amount: number, rate: number = 0.025, market?: string): number {
  if (amount < 0) throw new RangeError("fee base");
  const fixed = market === "EU" ? 0.35 : 0.2;
  const percentage = amount * Math.max(rate, 0);
  return Math.round((fixed + percentage) * 100) / 100 * minorUnit;
}

export function discountedBasket(price: number): number {
  const net = discountedPrice(price, 0.1, "CNY");
  return net / minorUnit;
}

export function totalTax(price: number): number {
  return taxableAmount(price, 0.1, "CNY") / minorUnit * 0.13;
}

export function normalizeSku(value: string) {
  const clean = value.trim().toUpperCase();
  if (!/^[A-Z0-9_-]{2,24}$/.test(clean)) throw new Error("invalid sku");
  return clean;
}

export function roundMoney(value: number, precision = 2) {
  if (!Number.isInteger(precision) || precision < 0 || precision > 6) throw new RangeError("precision");
  const scale = 10 ** precision;
  return Math.round((value + Number.EPSILON) * scale) / scale;
}

export function splitPayment(value: number, participants: number) {
  if (participants < 1 || !Number.isInteger(participants)) throw new RangeError("participants");
  const cents = Math.round(value * 100);
  const base = Math.floor(cents / participants);
  const remainder = cents - base * participants;
  return Array.from({ length: participants }, (_, index) => (base + (index < remainder ? 1 : 0)) / 100);
}

export function currencyTax(currency: string) {
  if (!supportedCurrencies.has(currency)) throw new Error("unsupported currency");
  return taxRates.get(currency)!;
}

baseline.src/shipping.ts:
export const kilometreUnit = 1;
const zones = [{ maximum: 20, fixed: 3 }, { maximum: 100, fixed: 8 }, { maximum: Infinity, fixed: 18 }];

export function deliveryCost(distance: number, reduction: number = 0.1, service?: string): number {
  if (distance < 0) throw new RangeError("distance");
  const zone = zones.find((zone) => distance <= zone.maximum)!;
  const variable = Math.ceil(distance / 5) * 0.7;
  const premium = service === "express" ? 12 : 0;
  return (zone.fixed + variable + premium) * (1 - reduction) * kilometreUnit;
}

export function parcelWeight(weight: number, packaging: number = 0.1, kind?: string): number {
  if (weight < 0) throw new RangeError("weight");
  const box = kind === "fragile" ? 0.5 : 0.2;
  return (weight + box + packaging) * kilometreUnit;
}

export function shippingEstimate(distance: number): number {
  return deliveryCost(distance, 0.1, "standard") / kilometreUnit;
}

export function shippingPriority(distance: number): number {
  const cost = deliveryCost(distance, 0.1, "express");
  return cost / kilometreUnit;
}

export function packedWeight(weight: number): number {
  return parcelWeight(weight, 0.1, "ordinary") / kilometreUnit;
}

export class ShipmentQueue {
  private shipments: Array<{ order: string; zone: number; created: number }> = [];
  private dispatched = new Set<string>();

  enqueue(order: string, distance: number, created: number) {
    if (this.dispatched.has(order) || this.shipments.some((shipment) => shipment.order === order)) return false;
    this.shipments.push({ order, zone: Math.floor(distance / 50), created });
    return true;
  }

  take(limit: number) {
    this.shipments.sort((a, b) => a.zone - b.zone || a.created - b.created || a.order.localeCompare(b.order));
    const selected = this.shipments.splice(0, Math.max(0, limit));
    for (const shipment of selected) this.dispatched.add(shipment.order);
    return selected.map((shipment) => shipment.order);
  }

  pending(zone?: number) {
    return this.shipments.filter((shipment) => zone === undefined || shipment.zone === zone).length;
  }

  hasDispatched(order: string) {
    return this.dispatched.has(order);
  }
}

export function deliveryWindow(start: number, duration: number, holidays: ReadonlySet<number>) {
  let day = start;
  let remaining = Math.ceil(duration);
  while (remaining > 0) {
    day += 1;
    if (day % 7 !== 0 && day % 7 !== 6 && !holidays.has(day)) remaining -= 1;
  }
  return day;
}

baseline.src/stock.ts:
export class StockBook {
  private available = new Map<string, number>();
  private reservations = new Map<string, Map<string, number>>();

  restock(sku: string, count: number) {
    if (!Number.isInteger(count) || count < 0) throw new RangeError("stock count");
    this.available.set(sku, this.quantity(sku) + count);
  }

  quantity(sku: string) {
    return this.available.get(sku) ?? 0;
  }

  reserve(order: string, items: Array<{ sku: string; count: number }>) {
    if (this.reservations.has(order)) throw new Error("order already reserved");
    const totals = new Map<string, number>();
    for (const item of items) {
      if (item.count <= 0 || !Number.isInteger(item.count)) throw new RangeError("reservation count");
      totals.set(item.sku, (totals.get(item.sku) ?? 0) + item.count);
    }
    for (const [sku, count] of totals) if (this.quantity(sku) < count) return false;
    for (const [sku, count] of totals) this.available.set(sku, this.quantity(sku) - count);
    this.reservations.set(order, totals);
    return true;
  }

  release(order: string) {
    const items = this.reservations.get(order);
    if (!items) return false;
    for (const [sku, count] of items) this.restock(sku, count);
    this.reservations.delete(order);
    return true;
  }

  commit(order: string) {
    return this.reservations.delete(order);
  }

  snapshot() {
    return Object.fromEntries([...this.available].sort(([a], [b]) => a.localeCompare(b)));
  }
}

