const supportedCurrencies = new Set(["CNY", "USD", "EUR"]);
const taxRates = new Map([["CNY", 0.13], ["USD", 0.07], ["EUR", 0.19]]);

/** 折扣使用比例，价格使用当前货币的主单位。 */
export function applyDiscount(price: number, rate: number = 0.1, currency?: string): number {
